            {"question":"Another routine childhood booster for tetanus-containing vaccine is given at:","options":["4–6 years","8–10 years","13–15 years","18–20 years"],"answer":"4–6 years"},
            {"question":"The Tdap booster is scheduled at approximately:","options":["4–6 years","11–12 years","18–24 months","30 years"],"answer":"11–12 years"},
