            {"question":"The vegetables and fruits section emphasizes:","options":["Only potatoes and starchy vegetables","Variety and color","Refined grains","Processed meats"],"answer":"Variety and color"},
            {"question":"According to the Healthy Eating Plate, which should be limited in the fruit and vegetable section?","options":["Leafy vegetables","Colorful fruits","Potatoes and starchy vegetables","Fresh vegetables"],"answer":"Potatoes and starchy vegetables"},
            {"question":"One quarter of the Healthy Eating Plate should consist of:","options":["Whole grains","Added sugars","Processed meats","Sugary beverages"],"answer":"Whole grains"},
            {"question":"Which food is an example of a recommended whole grain?","options":["Brown rice","Margarine","Sausage","Fruit juice"],"answer":"Brown rice"},
            {"question":"The Healthy Eating Plate recommends avoiding:","options":["Whole wheat","Oats","Refined grains","Brown rice"],"answer":"Refined grains"},
            {"question":"Which option BEST represents healthy proteins according to the lecture?","options":["Fish, poultry, legumes, and nuts","Sausages, luncheon meat, and pastries","Margarine, butter, and fried foods","Fruit juice and sugary beverages"],"answer":"Fish, poultry, legumes, and nuts"},
            {"question":"Which type of meat should be limited according to the Healthy Eating Plate?","options":["Poultry only","Fish only","Red and processed meats","All protein sources"],"answer":"Red and processed meats"},
            {"question":"Which oil is recommended as a healthy oil?","options":["Hydrogenated oil","Olive oil","Trans fat","Margarine"],"answer":"Olive oil"},
