            {"question":"The preferred drink in the Healthy Eating Plate is:","options":["Sugary beverages","Fruit juices","Water","Soft drinks"],"answer":"Water"},
            {"question":"Physical activity is shown beside the Healthy Eating Plate mainly to emphasize:","options":["Weekly fasting","Daily movement","Avoiding all exercise","Eating before exercise only"],"answer":"Daily movement"},
            {"question":"The recommended minimum intake of fruits and vegetables is:","options":["≥2 servings/day","≥3 servings/day","≥5 servings/day","≥10 servings/day"],"answer":"≥5 servings/day"},
            {"question":"Which food is an example of a recommended legume?","options":["Lentils","Margarine","Sausage","Pastry"],"answer":"Lentils"},
            {"question":"Which combination BEST represents recommended healthy fats?","options":["Olive oil, nuts, and seeds","Margarine, pastries, and fried foods","Sausages and luncheon meat","Sugary beverages and fruit juices"],"answer":"Olive oil, nuts, and seeds"},
            {"question":"Which of the following is a recommended low-fat dairy option?","options":["Yogurt","Fried foods","Processed meat","Margarine"],"answer":"Yogurt"},
            {"question":"Added sugars should provide:","options":["More than 25% of daily energy","Less than 10% of daily energy","Exactly 50% of daily energy","No limitation is recommended"],"answer":"Less than 10% of daily energy"},
