            {"question":"Which food should be limited as a processed meat?","options":["Chickpeas","Sausage","Whole wheat bread","Nuts"],"answer":"Sausage"},
            {"question":"According to WHO guidelines in the lecture, adults aged 18–64 years should perform:","options":["30–60 minutes/week of moderate activity","150–300 minutes/week of moderate-intensity aerobic activity","500 minutes/week of vigorous activity only","No aerobic activity"],"answer":"150–300 minutes/week of moderate-intensity aerobic activity"},
            {"question":"An alternative recommendation for adults is:","options":["75–150 minutes/week of vigorous-intensity activity","10 minutes/week of any activity","60 minutes/month of vigorous activity","300 minutes/day of moderate activity"],"answer":"75–150 minutes/week of vigorous-intensity activity"},
            {"question":"Muscle-strengthening activities are recommended for adults:","options":["At least 2 days/week","Once every month","Only during childhood","Only after age 65"],"answer":"At least 2 days/week"},
            {"question":"Which behavior should be reduced according to adult physical activity recommendations?","options":["Sedentary time","Daily movement","Muscle strengthening","Moderate activity"],"answer":"Sedentary time"},
            {"question":"Long periods of sitting should be:","options":["Increased gradually","Broken up","Maintained without interruption","Replaced only by sleep"],"answer":"Broken up"},
            {"question":"Children and adolescents aged 5–17 years should perform at least:","options":["30 minutes/week of activity","60 minutes/day of moderate to vigorous activity","150 minutes/month of activity","300 minutes/day of activity"],"answer":"60 minutes/day of moderate to vigorous activity"},
            {"question":"Physical activity for children and adolescents should include:","options":["Aerobic and bone-strengthening exercises","Only sedentary activities","Tobacco cessation only","Salt reduction only"],"answer":"Aerobic and bone-strengthening exercises"},
            {"question":"Physical activity recommendations for older adults include the same recommendations as adults with additional focus on:","options":["Balance and flexibility","Sugary beverages","Processed meat intake","Tobacco use"],"answer":"Balance and flexibility"},
