            {"question":"Routine screening for NCD prevention includes assessment of:","options":["Blood pressure, glucose, and BMI","Only body temperature","Only respiratory rate","Blood group only"],"answer":"Blood pressure, glucose, and BMI"},
            {"question":"Which individual-level strategy is MOST appropriate for a patient with a chronic NCD?","options":["Medication adherence and chronic disease management","Avoiding all health follow-up","Increasing sedentary time","Ignoring screening results"],"answer":"Medication adherence and chronic disease management"},
            {"question":"School and media campaigns are examples of:","options":["Health education","Environmental changes","Medication adherence","Genetic modification"],"answer":"Health education"},
            {"question":"Tobacco taxation and food labeling are examples of:","options":["Individual-level treatment","Policy and regulation","Genetic prevention","Clinical diagnosis"],"answer":"Policy and regulation"},
            {"question":"Salt reduction at the population level is an example of:","options":["Policy and regulation","Non-modifiable risk control","Genetic screening","Infectious disease isolation"],"answer":"Policy and regulation"},
            {"question":"Which intervention BEST represents an environmental change for NCD prevention?","options":["Walkable cities","Medication adherence","Individual BMI measurement","Family history assessment"],"answer":"Walkable cities"},
            {"question":"Clean air initiatives are classified under:","options":["Environmental changes","Individual medication management","Non-modifiable factors","Dietary supplements"],"answer":"Environmental changes"},
