            {"question":"Which of the following is a cause of polyuria that may contribute to urinary incontinence?","options":["Uncontrolled diabetes mellitus","Limited mobility","Smoking","Family history only"],"answer":"Uncontrolled diabetes mellitus"},
            {"question":"A patient drinks excessive amounts of fluid and develops excessive urine production. This is MOST consistent with:","options":["Primary polydipsia","Overflow incontinence","Structural incontinence","Functional incontinence"],"answer":"Primary polydipsia"},
            {"question":"A urinary tract infection may contribute to incontinence primarily by:","options":["Increasing pelvic floor strength","Irritating the bladder and causing strong urges to urinate","Increasing bladder capacity","Preventing urine production"],"answer":"Irritating the bladder and causing strong urges to urinate"},
            {"question":"Severe constipation may increase urinary frequency because:","options":["The rectum and bladder share some of the same nerves","Constipation increases bladder capacity","Stool improves urinary control","The pelvic floor becomes stronger"],"answer":"The rectum and bladder share some of the same nerves"},
            {"question":"A tumor obstructing the urinary tract may lead MOST directly to:","options":["Stress incontinence","Overflow incontinence","Functional incontinence","Bedwetting only"],"answer":"Overflow incontinence"},
            {"question":"Which substance is mentioned as a possible bladder stimulant or diuretic?","options":["Caffeine","Calcium","Protein","Fiber"],"answer":"Caffeine"},
            {"question":"According to the lecture, the most common cause of incontinence in men after the age of 40 is:","options":["Enlarged prostate","Pregnancy","Menopause","Ectopic ureter"],"answer":"Enlarged prostate"},
            {"question":"Which condition can interfere with nerve signals involved in bladder control?","options":["Parkinson's disease","Constipation only","Obesity only","Family history only"],"answer":"Parkinson's disease"},
            {"question":"Which patient has an increased risk of stress incontinence according to the lecture?","options":["A woman with pregnancy, childbirth, or menopause history","A man with an enlarged prostate only","A patient with normal bladder strength","A patient using a commode chair"],"answer":"A woman with pregnancy, childbirth, or menopause history"},
            {"question":"Men with prostate gland problems are at increased risk for:","options":["Stress incontinence only","Urge and overflow incontinence","Bedwetting only","Structural incontinence only"],"answer":"Urge and overflow incontinence"},
            {"question":"Aging increases the risk of urinary incontinence partly because:","options":["Bladder and urethral muscles lose strength","The bladder always increases its capacity","Pelvic muscles always become stronger","Urinary frequency always decreases"],"answer":"Bladder and urethral muscles lose strength"},
            {"question":"Being overweight may contribute to urinary incontinence because extra weight:","options":["Decreases pressure on the bladder","Increases pressure on the bladder and surrounding muscles","Eliminates leakage during coughing","Improves pelvic floor strength"],"answer":"Increases pressure on the bladder and surrounding muscles"},
            {"question":"Smoking may increase the risk of urinary incontinence through:","options":["Chronic cough","Increased bladder strength","Improved urinary flow","Increased pelvic muscle tone"],"answer":"Chronic cough"},
