            {"question":"Which intervention is MOST appropriate for a cognitively intact and motivated patient with urge incontinence?","options":["Urge inhibition education with bladder training","Permanent indwelling catheterization","Complete restriction of fluid intake","Avoiding all toileting programs"],"answer":"Urge inhibition education with bladder training"},
            {"question":"Which intervention is MOST appropriate for overflow urinary incontinence?","options":["Allow sufficient time for voiding","Encourage immediate fluid restriction","Use scheduled toileting only","Focus only on pelvic floor exercises"],"answer":"Allow sufficient time for voiding"},
            {"question":"If catheterization is necessary for overflow urinary incontinence, which method is preferred according to the lecture?","options":["Sterile intermittent catheterization","Permanent indwelling catheterization","No catheterization under any circumstances","Catheterization without assessment"],"answer":"Sterile intermittent catheterization"},
            {"question":"Which intervention BEST addresses functional urinary incontinence?","options":["Individualized scheduled, timed, or prompted voiding","Immediate surgical treatment for all patients","Permanent bed rest","Avoiding fluid intake"],"answer":"Individualized scheduled, timed, or prompted voiding"},
