            {"question":"Urinary stones may sometimes cause urine leakage.","options":["True","False"],"answer":"True"},
            {"question":"Brain disorders such as multiple sclerosis, Parkinson's disease, strokes, and spinal cord injury may interfere with bladder control.","options":["True","False"],"answer":"True"},
            {"question":"Family history, especially of urge incontinence, may increase the risk of developing urinary incontinence.","options":["True","False"],"answer":"True"},
